import {ROUNDS,messagesFor,externalPrompt,journalEntry} from './core.js';
const $=id=>document.getElementById(id), KEY='terror-figurengespraech-v1';
const figures=window.TERROR.roles.filter(f=>f.id!=='publikum');
let state={figure:'koch',passages:{},chats:{},notes:{},round:0,roundNotes:{},checks:{}};
try{const saved=JSON.parse(localStorage.getItem(KEY)||'null');if(saved?.chats && saved?.notes)state={...state,...saved};}catch{}
if(!figures.some(f=>f.id===state.figure))state.figure='koch';
state.round=Math.max(0,Math.min(ROUNDS.length-1,Number(state.round)||0));
let engine=null,worker=null,busy=false,loading=false,loadVersion=0;
let recognition=null,listening=false,speechVersion=0;
const SpeechRecognition=window.SpeechRecognition||window.webkitSpeechRecognition;
const figure=()=>figures.find(f=>f.id===state.figure);
const history=()=>state.chats[state.figure] ||= [];
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('save-status').textContent='Eingaben auf diesem Gerät gespeichert.';}catch{$('save-status').textContent='Speichern nicht möglich. Bitte Protokoll herunterladen, bevor ihr die Seite schliesst.';}}
function status(text){$('engine-status').textContent=text;}
function controls(){const locked=busy||loading;$('send').disabled=!engine||locked;$('load').disabled=!!engine||locked;$('unload').disabled=busy||(!engine&&!loading);$('stop').disabled=!busy;$('figure').disabled=locked;$('model').disabled=!!engine||locked;$('reset').disabled=locked;$('passage').disabled=locked;$('question').disabled=locked||listening;$('mic').disabled=locked||listening||!SpeechRecognition;$('mic-stop').disabled=!listening;$('send').disabled=$('send').disabled||listening;}
function renderChat(){const log=$('chat');log.replaceChildren();if(!history().length){const p=document.createElement('p');p.className='placeholder';p.textContent='Noch kein Gespräch. Formuliert zuerst euren Textbeleg und ladet dann die lokale KI – oder nutzt die externe Vergleichsaufgabe.';log.append(p);}for(const m of history()){const p=document.createElement('div');p.className=`message ${m.role}`;const who=document.createElement('b');who.textContent=m.role==='user'?'Eure Frage':`KI-Rollenspiel · ${figure().name}${m.stopped?' · abgebrochen':''}${m.failed?' · unvollständig':''}`;const text=document.createElement('span');text.textContent=m.content||'Antwort wird erzeugt …';p.append(who,text);log.append(p);}log.scrollTop=log.scrollHeight;const n=history().filter(m=>m.role==='assistant'&&!m.failed).length;$('turn-hint').textContent=n>=3?`Bisher ${n} Antworten. ${n%6<3?'Person A fragt, Person B prüft.':'Rollenwechsel: Person B fragt, Person A prüft.'} Nach sechs Fragen eine Gegenfigur wählen.`:'Person A fragt; Person B prüft am Text. Nach drei Antworten wechseln.';}
function renderFigure(){const f=figure();$('chat-title').textContent=`Gespräch mit ${f.name}`;$('profile').replaceChildren();for(const [label,value] of [['Rolle',f.function],['Wissen und Grenze',f.knowledge],['Gegenfrage',f.challenge]]){const p=document.createElement('p');const b=document.createElement('b');b.textContent=label+': ';p.append(b,document.createTextNode(value));$('profile').append(p);}$('passage').value=state.passages[f.id]||'';renderChat();makePrompt();}
function makePrompt(){$('prompt').value=externalPrompt(figure(),$('passage').value,$('external-question').value);}
for(const f of figures){const o=document.createElement('option');o.value=f.id;o.textContent=f.name;$('figure').append(o);}$('figure').value=state.figure;
$('figure').onchange=()=>{state.figure=$('figure').value;save();renderFigure();};
$('passage').oninput=()=>{state.passages[state.figure]=$('passage').value;save();makePrompt();};
for(const el of document.querySelectorAll('[data-save]')){el.value=state.notes[el.id]||'';el.oninput=()=>{state.notes[el.id]=el.value;save();if(el.id==='external-question')makePrompt();};}
for(const el of document.querySelectorAll('[data-check]')){el.checked=!!state.checks[el.dataset.check];el.onchange=()=>{state.checks[el.dataset.check]=el.checked;save();};}
$('load').onclick=async()=>{const version=++loadVersion;loading=true;controls();$('progress').hidden=false;status('WebGPU wird geprüft …');try{if(!navigator.gpu)throw new Error('Dieser Browser bietet kein WebGPU. Nutzt aktuelles Chrome/Edge auf einem geeigneten Gerät oder die externe Variante unten.');const adapter=await navigator.gpu.requestAdapter();if(!adapter)throw new Error('Keine geeignete Grafikkarte verfügbar. Nutzt die externe Variante unten.');const quant=adapter.features.has('shader-f16')?'q4f16_1':'q4f32_1';const model=`Qwen2.5-${$('model').value}B-Instruct-${quant}-MLC`;status('Programm und Modell werden geladen. Der erste Download kann mehrere Minuten dauern.');const {CreateWebWorkerMLCEngine}=await import('https://cdn.jsdelivr.net/npm/@mlc-ai/web-llm@0.2.88/+esm');if(version!==loadVersion)return;worker=new Worker(new URL('./engine-worker.js',import.meta.url),{type:'module'});let timeout;try{engine=await Promise.race([CreateWebWorkerMLCEngine(worker,model,{initProgressCallback:p=>{if(version===loadVersion){$('progress').value=p.progress;status(`Modell laden: ${Math.round(p.progress*100)} % · ${p.text}`);}}}),new Promise((_,reject)=>{timeout=setTimeout(()=>reject(new Error('Das Laden dauert länger als fünf Minuten. Prüft Netzwerk und Grafikspeicher oder verwendet die externe Variante.')),300000);})]);}finally{clearTimeout(timeout);}if(version!==loadVersion){engine=null;return;}status(`Bereit · ${model}. Fragen werden auf eurem Gerät verarbeitet.`);$('progress').value=1;}catch(e){if(version!==loadVersion)return;worker?.terminate();worker=null;engine=null;status(`Lokale KI nicht bereit: ${e.message}`);}finally{if(version===loadVersion){loading=false;controls();}}};
$('unload').onclick=()=>{++loadVersion;worker?.terminate();worker=null;engine=null;loading=false;$('progress').hidden=true;status('KI entladen. Eure Protokolle bleiben erhalten.');controls();};
$('chat-form').onsubmit=async event=>{event.preventDefault();if(!engine||busy||loading)return;const question=$('question').value.trim();if(!question)return;busy=true;controls();const chat=history();const messages=messagesFor(figure(),$('passage').value,chat,question);chat.push({role:'user',content:question},{role:'assistant',content:''});const reply=chat.at(-1);$('question').value='';renderChat();status('Die Figur antwortet lokal …');try{const chunks=await engine.chat.completions.create({messages,stream:true,temperature:0.4,max_tokens:220});for await(const chunk of chunks){reply.content+=chunk.choices[0]?.delta?.content||'';renderChat();}if(!reply.content.trim())throw new Error('Das Modell hat keine Antwort erzeugt. Frage kürzer formulieren oder neu laden.');status('Antwort fertig. Prüft jetzt eine konkrete Behauptung am Text.');}catch(e){reply.failed=true;status(`Antwort unvollständig: ${e.message}. Der Text ist kein geprüfter Beleg.`);}finally{busy=false;save();controls();}};
$('stop').onclick=()=>{if(!engine)return;const reply=history().at(-1);if(reply?.role==='assistant')reply.stopped=true;engine.interruptGenerate();status('Antwort wird gestoppt. Prüft den unvollständigen Text besonders sorgfältig.');};
function endSpeech(abort=false){if(!recognition)return;abort?recognition.abort():recognition.stop();}
$('mic').onclick=()=>{
 if(!SpeechRecognition||busy||loading||listening)return;
 const session=++speechVersion, prefix=$('question').value.trim();let finalText='';
 const rec=new SpeechRecognition();recognition=rec;rec.lang='de-CH';rec.continuous=true;rec.interimResults=true;
 rec.onstart=()=>{if(session!==speechVersion)return;listening=true;controls();$('speech-status').textContent='Mikrofon aktiv. Sprecht eure Frage. Danach Diktat beenden und den Text prüfen.';};
 rec.onresult=event=>{if(session!==speechVersion)return;let complete='',interim='';for(let i=0;i<event.results.length;i++){const r=event.results[i];if(r.isFinal)complete+=r[0].transcript+' ';else interim+=r[0].transcript+' ';}finalText=complete.trim();$('question').value=[prefix,complete.trim(),interim.trim()].filter(Boolean).join(' ').slice(0,700);};
 rec.onerror=event=>{if(session!==speechVersion)return;const errors={'not-allowed':'Mikrofonzugriff nicht erlaubt. Gebt die Frage per Tastatur ein oder erlaubt den Zugriff in den Website-Einstellungen.','audio-capture':'Kein Mikrofon verfügbar. Prüft das angeschlossene Gerät.','no-speech':'Keine Sprache erkannt. Ihr könnt erneut diktieren oder tippen.','network':'Der Sprachdienst ist nicht erreichbar. Tippt eure Frage stattdessen.'};$('speech-status').textContent=errors[event.error]||'Diktat unterbrochen. Prüft den vorhandenen Text und nutzt bei Bedarf die Tastatur.';};
 rec.onend=()=>{if(session!==speechVersion)return;listening=false;recognition=null;controls();if(finalText)$('speech-status').textContent='Diktat als Entwurf übernommen. Prüft Namen, Satzzeichen und Sinn; erst dann «Frage stellen» wählen.';};
 listening=true;controls();
 try{rec.start();}catch{listening=false;recognition=null;$('speech-status').textContent='Spracheingabe konnte nicht starten. Nutzt die Tastatur.';controls();}
};
$('mic-stop').onclick=()=>endSpeech();
window.addEventListener('pagehide',()=>{++speechVersion;endSpeech(true);worker?.terminate();});
if(!SpeechRecognition)$('speech-status').textContent='Dieser Browser unterstützt kein Diktat. Bitte die Frage tippen oder einen kompatiblen Browser verwenden.';
$('reset').onclick=()=>{if(!history().length)return;if(!window.confirm('Nur das Gespräch mit dieser Figur leeren? Notizen und andere Gespräche bleiben erhalten.'))return;state.chats[state.figure]=[];save();renderChat();};
$('make-prompt').onclick=makePrompt;
$('copy-prompt').onclick=async()=>{makePrompt();try{await navigator.clipboard.writeText($('prompt').value);$('save-status').textContent='Arbeitsauftrag kopiert. Fügt ihn selbst bei eurer externen KI ein.';}catch{$('prompt').focus();$('prompt').select();$('save-status').textContent='Text markiert. Bitte mit Strg+C bzw. Cmd+C kopieren.';}};
function renderRound(){const [title,task,intervention]=ROUNDS[state.round];$('round-count').textContent=`RUNDE ${state.round+1} VON ${ROUNDS.length}`;$('round-title').textContent=title;$('round-task').textContent=task;$('round-intervention').textContent=intervention;$('round-note').value=state.roundNotes[state.round]||'';$('previous').disabled=state.round===0;$('next').disabled=state.round===ROUNDS.length-1;}
$('round-note').oninput=()=>{state.roundNotes[state.round]=$('round-note').value;save();};
$('previous').onclick=()=>{state.round=Math.max(0,state.round-1);save();renderRound();};$('next').onclick=()=>{state.round=Math.min(ROUNDS.length-1,state.round+1);save();renderRound();};
function report(){let text=`# TERROR · Figurengespräche und Textprüfung\n\nDatum: ${new Date().toLocaleDateString('de-CH')}\nKI-Rollenspiel, kein Originaltext.\n\n`;for(const f of figures){const chat=state.chats[f.id]||[];if(chat.length)text+=`## ${f.name}\n\nTextgrundlage: ${state.passages[f.id]||'keine'}\n\n`+chat.map(m=>`**${m.role==='user'?'Frage':'KI-Antwort'}${m.stopped||m.failed?' (unvollständig)':''}:** ${m.content}`).join('\n\n')+'\n\n';}for(const [id,label] of [['audit','Textprüfung'],['comparison','Vergleich mit externer KI'],['synthesis','Eigene Ergänzung aus der Lektüre']])text+=`## ${label}\n\n${state.notes[id]||'Noch nicht notiert.'}\n\n`;text+=`## Externer Arbeitsauftrag\n\n${$('prompt').value}\n\n## Diskussion\n\n`;ROUNDS.forEach((r,i)=>{text+=`### ${r[0]}\n\n${state.roundNotes[i]||'Noch nicht notiert.'}\n\n`;});return text;}
$('export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([report()],{type:'text/markdown;charset=utf-8'}));a.download='terror-figurengespraeche.md';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('journal').onclick=()=>{try{const old=JSON.parse(localStorage.getItem('terror-learning-v1')||'null');const updated=journalEntry(old,report());localStorage.setItem('terror-learning-v1',JSON.stringify(updated));$('save-status').textContent='Als neuer Eintrag im Hauptjournal gespeichert. Vorhandene Einträge bleiben erhalten.';}catch(e){$('save-status').textContent=`Journal konnte nicht ergänzt werden: ${e.message}. Bitte das Protokoll herunterladen.`;}};
renderFigure();renderRound();controls();if(!navigator.gpu)status('Auf diesem Gerät ist kein WebGPU verfügbar. Ihr könnt die externe Variante mit Kopiervorlage und die vollständige Diskussionsrunde nutzen.');
